// Step 1: Prepare Ingestion Context for Source Text
const input = $input.first().json;

const userId = input.user_id;
const ingestionId = input.ingestion_id;
const textContent = input.text || '';
const sourceKey = 'tg_msg_' + (input.message_id || Date.now());
const isEdited = Boolean(input.is_edited);

return [{
  json: {
    ...input,
    user_id: userId,
    ingestion_id: ingestionId,
    text_content: textContent,
    source_key: sourceKey,
    source_kind: isEdited ? 'edited_text' : 'telegram_text'
  }
}];

const req = $('Prepare Source Text Payload').first().json;
const stRaw = $input.first().json.st_res;
const st = typeof stRaw === 'string' ? JSON.parse(stRaw) : stRaw;

return [{
  json: {
    ...req,
    source_text_id: st.source_text_id,
    version_no: st.version_no
  }
}];

// Post-AI Router: Validates Interpretation and Dispatches to Specialized Workflows
const input = $input.first().json;
const interp = input.interpretation || input;

const intent = interp.intent || 'note';
const requiresClarification = Boolean(interp.requires_clarification);

let nextStep = 'apply_actions';
let responseText = '';

if (requiresClarification) {
  nextStep = 'clarification';
  responseText = (interp.clarification_questions && interp.clarification_questions[0]) || '¿Podrías especificar a qué te refieres?';
} else if (['query_memory', 'evidence_request', 'correction', 'report_request'].includes(intent)) {
  nextStep = 'unsupported_f1';
  responseText = 'Esta función no está disponible en la fase actual del sistema.';
} else if (intent === 'query_tasks') {
  nextStep = 'query_tasks';
} else if (['create_task', 'update_task', 'complete_task', 'postpone_task', 'cancel_task'].includes(intent)) {
  nextStep = 'task_action';
} else {
  nextStep = 'note_memory';
}

return [{
  json: {
    ...input,
    intent: intent,
    next_step: nextStep,
    initial_response_text: responseText
  }
}];

const state = $('Route Interpretation Intent').first().json;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: state.correlation_id,
    data: {
      source_text_id: state.source_text_id,
      intent: state.intent,
      next_step: state.next_step,
      response_text: state.initial_response_text
    }
  }
}];
